"""All acquisitions are scratch; detected leaks are always released by the test."""
import dis,errno,json,os,sys,types
from pathlib import Path
import pytest
from subfleet import retention_fs as rfs
from tests.unit.test_retention_descriptor_review import raise_at
from tests.unit.test_retention_walk_descriptors import DEEP,tree
ROOT=Path('/private/tmp/sf-r279r4')

def evidence(name,**details):
    (ROOT/'probe-records').mkdir(exist_ok=True)
    key=name+'-'+sys.version.split()[0]+'-'+os.environ.get('R4_HOLD_LABEL','unknown')
    (ROOT/'probe-records'/f'{key}.json').write_text(json.dumps(details,indent=2))
    print('R4_PROBE',name,json.dumps(details))

def alive(fds):
    out=[]
    for fd in fds:
        try: os.fstat(fd)
        except OSError: pass
        else: out.append(fd)
    return out

def release_module():
    name='subfleet._r4_release'
    if name not in sys.modules:
        m=types.ModuleType(name)
        sys.modules[name]=m
        exec(compile((ROOT/'release_fs.py').read_text(),'<release a093fb4b6>','exec'),m.__dict__)
    return sys.modules[name]

@pytest.mark.xfail(strict=True,reason='P2-6: new post-open owner construction/entry leaves fd unowned')
@pytest.mark.parametrize('phase',['construction','entry'])
@pytest.mark.parametrize('fault',['memory','keyboard'])
def test_owner_setup_failure_closes_acquired_file(tmp_path,monkeypatch,phase,fault):
    p=tmp_path/'file'; p.write_bytes(b'scratch')
    injected=MemoryError('owner setup') if fault=='memory' else KeyboardInterrupt('owner setup')
    method=rfs._cleanup.__init__ if phase=='construction' else rfs._cleanup.__enter__
    code=method.__code__
    at=next(i.offset for i in dis.get_instructions(code) if i.opname!='RESUME')
    original_open,original_close=os.open,os.close
    opened=[]; attempted=[]; caught=None
    def open_(*args,**kw):
        fd=original_open(*args,**kw); opened.append(fd); return fd
    def close(fd):
        attempted.append(fd); return original_close(fd)
    try:
        with monkeypatch.context() as patch:
            patch.setattr(os,'open',open_); patch.setattr(os,'close',close)
            with raise_at(code,at,injected) as fired:
                try:rfs.read_regular(p)
                except BaseException as exc:caught=exc
        leaked=alive(opened)
        evidence(f'owner-{phase}-{fault}',offset=at,fired=fired,opened=opened,attempted=attempted,leaked=leaked,identity=caught is injected)
        assert fired and caught is injected
        assert not leaked
    finally:
        for fd in alive(opened):original_close(fd)

@pytest.mark.parametrize('fault',['memory','keyboard'])
def test_release_first_body_failure_is_protected(tmp_path,monkeypatch,fault):
    p=tmp_path/'file';p.write_bytes(b'scratch')
    base=release_module(); original_open,original_close=os.open,os.close
    injected=MemoryError('first body') if fault=='memory' else KeyboardInterrupt('first body')
    opened=[]; attempted=[]
    def open_(*args,**kw):
        fd=original_open(*args,**kw);opened.append(fd);return fd
    def close(fd):attempted.append(fd);original_close(fd)
    def fstat(fd):raise injected
    try:
        with monkeypatch.context() as patch:
            patch.setattr(os,'open',open_);patch.setattr(os,'close',close);patch.setattr(os,'fstat',fstat)
            with pytest.raises(type(injected)) as caught:base.read_regular(p)
